        bool r3;
        c.SetMinSum(_val); bool __rev2 = __ESBMC_reverted(); if (__rev2) { r3 = true; } else { r3 = false; }
        bool r4;
        c.Initialized(); bool __rev3 = __ESBMC_reverted(); if (__rev3) { r4 = true; } else { r4 = false; }
        bool r5;
